# -*- coding: utf-8 -*-
# Numeric key-vs-statement review 25.09, part 2 (Algebra 7/8 school editions, Makarychev 7/8): each decision by hand,
# re-verified numerically by verify_fix.py. Where the statement was checked against the book, the note says so.
KW = "ключ не совпадал с выражением из условия (численная проверка, пересчитано вручную): "
QG = "в условии была искажена запись, ключ верен для восстановленного условия: "
BK8 = " (условие совпадает с учебником Алгебра 8, № {})"
P = {}
def K(t, k, note): P[t] = {"k": k, "why": KW + note}
def Q(t, a, b, note, k=None):
    P[t] = {"qrep": (a, b), "why": QG + note}
    if k: P[t]["k"] = k

K("G7_ALG_25_6.3", r"$mn$", "m³ − n³ = (m − n)(m² + mn + n²), m³ + n³ = (m + n)(m² − mn + n²), m⁴ + m²n² + n⁴ = (m² + mn + n²)(m² − mn + n²) — всё сокращается до mn (было mn(m² + mn + n²))")
K("G7_ALG_39_12.4", r"$1\dfrac{4}{7}$", "при a = 1, b = −3: (1 − 12)/(2 − 9) = 11/7 (было 1/4)")
K("G7_ALG_5_6.1", r"$-32{,}5$", "5(3x − 7) + 2(1 − x) = 13x − 33; при x = 1/26 это 0,5 − 33 = −32,5 (было −32)")
K("G7_ALG_5_6.3", r"$20{,}6$", "1,3(a + b) + 2,7(a − b) = 4a − 1,4b = 8 + 12,6 = 20,6 (было 23)")
K("G7_ALG_9_1.7", r"$-\dfrac{1}{6}xy$", "ключ был записан как −1/(6xy) (переменные в знаменателе); ½x·(−⅓y) = −⅙xy")
K("G7_TB_21_474.3", r"$-2$", "0,5·(−2)²·(−1)³ = 0,5·4·(−1) = −2 (было 2)")
