K("G7_TB_35_909.2", r"$\left(\dfrac{4}{3}x - y\right)\left(\dfrac{4}{3}x + y\right)$", "ключ был записан с x в знаменателе (4/(3x)); 1 7/9 x² − y² = (4/3 x − y)(4/3 x + y)")
K("G7_TB_35_920.2", r"$\left(\dfrac{8}{5}x^{2} - \dfrac{6}{5}y\right)\left(\dfrac{8}{5}x^{2} + \dfrac{6}{5}y\right)$", "ключ был записан с x², y в знаменателях; 2 14/25 x⁴ − 1 11/25 y² = (8/5 x² − 6/5 y)(8/5 x² + 6/5 y)")
K("G7_TB_36_933.3", r"$\left(\dfrac{1}{3}x + \dfrac{1}{5}y\right)\left(\dfrac{1}{9}x^{2} - \dfrac{1}{15}xy + \dfrac{1}{25}y^{2}\right)$", "ключ был записан с x, y в знаменателях; сумма кубов (x/3)³ + (y/5)³")
K("G7_ALG_17_17.3", r"$\dfrac{1}{6}m^{2} - \dfrac{1}{6}n^{2}$", "(⅕m − ⅕n)(⅚m + ⅚n) = ⅙(m² − n²) (было m² − n²)")
K("G7_ALG_17_17.4", r"$\dfrac{1}{4}x^{2} - \dfrac{1}{4}y^{2}$", "(¾x + ¾y)(⅓x − ⅓y) = ¼(x² − y²) (было x² − y²)")
K("G8_ALG_10_148.2", r"$\dfrac{55b-61}{24}$", "(6(b − 7) + 8(5b − 2) + 3(3b − 1))/24 = (55b − 61)/24 (было 55b − 71)")
K("G8_ALG_10_148.3", r"$\dfrac{28-7a}{45}$", "((a − 2) − 3(a + 5) − 5(a − 9))/45 = (28 − 7a)/45 (было 28 − 4a)")
K("G8_ALG_10_148.4", r"$\dfrac{5-27b}{36}$", "(3b − 4(3b + 1) − 9(2b − 1))/36 = (5 − 27b)/36 (было −(27b + 5)/36)")
K("G8_ALG_32_549.2", r"$-\dfrac{2n(k-2n)}{k+2n}$", "первая скобка 2nk/(k + 2n)², вторая −k/((k − 2n)(k + 2n)); частное −2n(k − 2n)/(k + 2n) (было −2n/k)" + BK8.format("549 (2)"))
K("G8_ALG_32_549.3", r"$-\dfrac{b(b-x)}{b+x}$", "первая скобка b²x/(b + x)², вторая −bx/((b − x)(b + x)); частное −b(b − x)/(b + x) (было −bx/(b + x))" + BK8.format("549 (3)"))
K("G8_ALG_32_549.4", r"$-\dfrac{2q(2q-m)}{2q+m}$", "первая скобка 2qm/(2q + m)², вторая −m/((2q − m)(2q + m)); частное −2q(2q − m)/(2q + m) (было −2q/m)" + BK8.format("549 (4)"))
K("G8_ALG_32_550.1", r"$\dfrac{1+a-a^{2}}{2a}$", "1 − a/2 − (a − 1)/(2a) = (1 + a − a²)/(2a) (было (1 − a)/(2a))" + BK8.format("550 (1)"))
K("G8_ALG_32_550.2", r"$\dfrac{3}{1-m^{3}}$", "числитель над общим знаменателем 1 − m³ равен 3 (было 3/(1 − m))" + BK8.format("550 (2)"))
K("G8_ALG_32_551.1", r"$(a+1)^{2}$", "a²(a + 2)/((a − 1)(a + 1)) · (a + 1)³(a − 1)/(a²(a + 2)) = (a + 1)² (было a(a + 1)²)")
K("G8_ALG_32_551.2", r"$\dfrac{a^{2}b^{2}(a-b)}{a+b}$", "a²(a + b)²/((a − b)(a + b)) · b²(a − b)²/(a + b)² = a²b²(a − b)/(a + b) (было a²b²(a − b))")
K("G8_ALG_32_552.1", r"$4\dfrac{4}{7} - 5\dfrac{11}{14}b$", "33b/14 − (36b/7 − 60/7) − (3b + 4) = 32/7 − 81b/14 (было 4 4/7 − 5 4/7 b)" + BK8.format("552 (1)"))
K("G8_ALG_32_552.2", r"$1$", "после деления третье слагаемое равно (2a² − ax + x²)/(x² − a²), сумма = (x² − a²)/(x² − a²) = 1 (было (a − x)/(a + x))" + BK8.format("552 (2)"))
K("G8_ALG_32_569.1", r"$-\dfrac{1}{3}$", "выражение равно (√a − √b)/(√a + √b); при a = 3, b = 12 это −√3/(3√3) = −1/3 (было −1)" + BK8.format("569 (1)"))
K("G8_ALG_32_569.2", r"$-4\dfrac{5}{6}$", "выражение равно (√m + √n)²/(√n(√m − √n)) − √m/(√m + √n); при m = 5, n = 20: −4,5 − 1/3 = −4 5/6 (было 2)" + BK8.format("569 (2)"))
K("G8_ALG_4_54.1", r"$\dfrac{10p^{2}}{q^{2}}$", "p²/q² + 9p²/q² = 10p²/q² (было (4p/q)²)")
K("G8_ALG_4_54.2", r"$\dfrac{485a^{3}}{b^{3}}$", "512a³/b³ − 27a³/b³ = 485a³/b³ (было (5a/b)³)")
K("G8_ALG_4_59.5", r"$\dfrac{9n+4m}{m^{2}n}$", "9/m² + 4/(mn) = (9n + 4m)/(m²n) (было (3n + 4m)/m^{2n})")
K("G8_ALG_4_60.5", r"$\dfrac{a^{4}c^{2} + a^{2}b^{4} + b^{2}c^{4}}{a^{2}b^{2}c^{2}}$", "общий знаменатель a²b²c² (в ключе были искажены показатели)")
K("G8_ALG_4_68.2", r"$\dfrac{2-11x}{(3x+1)^{2}}$", "(4 − 5x − 2(3x + 1))/(3x + 1)² = (2 − 11x)/(3x + 1)² (было 2((1 − 11x)/(3x + 1))²)")
K("G8_ALG_4_69.2", r"$\dfrac{b(b-3)}{b-2}$", "(b² − 2b − b)/(b − 2) = b(b − 3)/(b − 2) (было (b − 3)/(b − 2))")
K("G8_ALG_4_71.5", r"$-\dfrac{x^{2}y}{x^{2}-y^{2}}$", "(x³ − xy² − x²y + xy² − x³)/(x² − y²) = −x²y/(x² − y²) (было −xy²/(x² − y²))")
K("G8_ALG_4_72.1", r"$\dfrac{2}{a^{3}-1}$", "(a + 1 − (a − 1))/(a³ − 1) = 2/(a³ − 1) (было (2 − a)/(a³ − 1))")
K("G8_ALG_4_72.2", r"$\dfrac{2a}{a^{3}+8}$", "(a² + 4 − (a² − 2a + 4))/(a³ + 8) = 2a/(a³ + 8) (было (2 − a)/(a³ + 8))")
K("G8_ALG_4_72.3", r"$\dfrac{3ab}{a^{3}+b^{3}}$", "((a + b)² − (a² − ab + b²))/(a³ + b³) = 3ab/(a³ + b³) (было ab/(a³ + b³))")
K("G8_ALG_6_88.3", r"$a - b$", "((a − b)²/(ab)) : ((a − b)/(ab)) = a − b (было (a − b)/(ab))")
K("G8_ALG_6_88.4", r"$\dfrac{2(m+n)}{n}$", "((m + n)²/(mn)) · (2m/(m + n)) = 2(m + n)/n (было 2(m + n)²/(mn))")
K("G8_ALG_6_89.1", r"$\dfrac{4ab}{a^{2}-b^{2}}$", "(2b/(a + b)) · (2a/(a − b)) = 4ab/(a² − b²) (было 4b/(a + b))")
K("G8_ALG_6_89.2", r"$\dfrac{4ab}{a^{2}-b^{2}}$", "(2a/(a − b)) · (2b/(a + b)) = 4ab/(a² − b²) (было 4a/(a − b))")
K("G8_ALG_9_128.1", r"$\dfrac{a(5b-a)}{a-b}$", "(a² − a√(ab) + a√(ab) + ab − 2a² + 4ab)/(a − b) = a(5b − a)/(a − b) (было a)" + BK8.format("128 (1)"))
K("G8_ALG_9_128.2", r"$2y$", "(3xy − y² − y√(xy) − y² − xy + y√(xy))/(x − y) = 2y(x − y)/(x − y) = 2y (было y)" + BK8.format("128 (2)"))
K("G8_TB_11_285.3", r"$\dfrac{a}{1-a^{3}}$", "над общим знаменателем a³ − 1 числитель 3a² − a + 3 − (a − 1)² − 2(a² + a + 1) = −a (было 0; условие совпадает с учебником Макарычев 8, № 285 в))")
Q("G7_ALG_2_1.3", "\\dfrac{1}{5b}", "\\dfrac{1}{5}b", "b попал в знаменатель (1/(5b) вместо ⅕b); с ⅕b: 2·9 + 5 = 23")
Q("G7_TB_39_1026.3", "a^{4b} + 6a^{2b} b^{3}", "a^{4}b + 6a^{2}b^{3}", "множитель b попал в показатель степени")
for t in ("G7_TB_3_42.1", "G7_TB_3_42.2", "G7_TB_3_42.3"):
    Q(t, "\\dfrac{1}{2x}", "\\dfrac{1}{2}x", "x попал в знаменатель (1/(2x) вместо ½x); ключи подпунктов а)–в) верны для ½x − y")
Q("G7_TB_3_42.4", "\\dfrac{1}{2x}", "\\dfrac{1}{2}x", "x попал в знаменатель (1/(2x) вместо ½x); при x = −4, y = −3: −2 + 3 = 1 (было 0,8)", k=r"$1$")
